section.programlisting:
Path model = Path.of("model.onnx");
Map<String, String> options = Map.of("vocabulary", "vocab.txt");
TextEmbedderProvider provider = TextEmbedderProviders.select(model, options);
try (TextEmbedder embedder = provider.load(model, options)) {
  float[][] vectors = embedder.embedAll(List.of("first sentence", "second sentence"));
}
